package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.Device;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 设备登记表数据访问。型号、硬件型号与分桶号登记后不可修改。
 */
@Repository
public class DeviceRepository {

    private final JdbcTemplate jdbc;

    public DeviceRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(Device device) {
        jdbc.update("INSERT INTO device (device_id, model, hardware_model, current_version, bucket_no)"
                        + " VALUES (?, ?, ?, ?, ?)",
                device.deviceId(), device.model(), device.hardwareModel(),
                device.currentVersion(), device.bucketNo());
    }

    public Optional<Device> findById(String deviceId) {
        return jdbc.query("SELECT device_id, model, hardware_model, current_version, bucket_no"
                        + " FROM device WHERE device_id = ?",
                (rs, rowNum) -> new Device(rs.getString("device_id"), rs.getString("model"),
                        rs.getString("hardware_model"), rs.getString("current_version"), rs.getInt("bucket_no")),
                deviceId).stream().findFirst();
    }

    public void updateCurrentVersion(String deviceId, String newVersion) {
        jdbc.update("UPDATE device SET current_version = ? WHERE device_id = ?", newVersion, deviceId);
    }

    /**
     * 已登记设备中出现过的全部硬件型号（用于兼容矩阵配置的未知型号校验）。
     */
    public List<String> findDistinctHardwareModels() {
        return jdbc.query("SELECT DISTINCT hardware_model FROM device",
                (rs, rowNum) -> rs.getString(1));
    }

    /**
     * 发布单候选设备：型号匹配、当前版本等于来源版本且分桶号落入投放比例。
     */
    public List<Device> findCandidates(String model, String fromVersion, int ratio) {
        return jdbc.query("SELECT device_id, model, hardware_model, current_version, bucket_no"
                        + " FROM device WHERE model = ? AND current_version = ? AND bucket_no < ?",
                (rs, rowNum) -> new Device(rs.getString("device_id"), rs.getString("model"),
                        rs.getString("hardware_model"), rs.getString("current_version"), rs.getInt("bucket_no")),
                model, fromVersion, ratio);
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ReceiptResult;
import com.example.starter.firmware.domain.RolloutTask;
import com.example.starter.firmware.domain.TaskStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.util.List;
import java.util.Optional;

/**
 * 投放任务数据访问。同设备同发布单由唯一约束 uk_task_release_device 保证最多一条。
 * 任务创建时固化目标固件当时的兼容矩阵版本（compat_version）。
 */
@Repository
public class TaskRepository {

    private static final RowMapper<RolloutTask> MAPPER = (rs, rowNum) -> {
        String firstResult = rs.getString("first_result");
        return new RolloutTask(rs.getLong("id"), rs.getLong("release_id"), rs.getString("device_id"),
                TaskStatus.valueOf(rs.getString("status")),
                firstResult == null ? null : ReceiptResult.valueOf(firstResult),
                rs.getInt("compat_version"));
    };

    private static final String COLUMNS = "id, release_id, device_id, status, first_result, compat_version";

    private final JdbcTemplate jdbc;

    public TaskRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public long insert(long releaseId, String deviceId, int compatVersion) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO rollout_task (release_id, device_id, status, compat_version)"
                            + " VALUES (?, ?, 'PENDING', ?)",
                    new String[]{"id"});
            ps.setLong(1, releaseId);
            ps.setString(2, deviceId);
            ps.setInt(3, compatVersion);
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public Optional<RolloutTask> findById(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE id = ?", MAPPER, id)
                .stream().findFirst();
    }

    public Optional<RolloutTask> findByIdForUpdate(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE id = ? FOR UPDATE", MAPPER, id)
                .stream().findFirst();
    }

    public Optional<RolloutTask> findByReleaseAndDevice(long releaseId, String deviceId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? AND device_id = ?",
                MAPPER, releaseId, deviceId).stream().findFirst();
    }

    public void complete(long id, ReceiptResult result) {
        jdbc.update("UPDATE rollout_task SET status = ?, first_result = ?, updated_at = CURRENT_TIMESTAMP"
                + " WHERE id = ?", result.name(), result.name(), id);
    }

    public int cancelPendingByRelease(long releaseId) {
        return jdbc.update("UPDATE rollout_task SET status = 'CANCELLED', updated_at = CURRENT_TIMESTAMP"
                + " WHERE release_id = ? AND status = 'PENDING'", releaseId);
    }

    public List<RolloutTask> findByRelease(long releaseId, TaskStatus statusFilter) {
        if (statusFilter == null) {
            return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? ORDER BY id",
                    MAPPER, releaseId);
        }
        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? AND status = ? ORDER BY id",
                MAPPER, releaseId, statusFilter.name());
    }

    public long countByReleaseAndDevice(long releaseId, String deviceId) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rollout_task WHERE release_id = ? AND device_id = ?",
                Long.class, releaseId, deviceId);
        return count == null ? 0 : count;
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.FirmwareCompat;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 固件硬件兼容矩阵数据访问。allowed_models 以升序去重的 JSON 数组存储，
 * 矩阵修改通过 SELECT ... FOR UPDATE 行锁与版本校验串行化。
 */
@Repository
public class FirmwareCompatRepository {

    private static final TypeReference<List<String>> MODEL_LIST = new TypeReference<>() {
    };

    private final JdbcTemplate jdbc;
    private final ObjectMapper objectMapper;

    public FirmwareCompatRepository(JdbcTemplate jdbc, ObjectMapper objectMapper) {
        this.jdbc = jdbc;
        this.objectMapper = objectMapper;
    }

    public Optional<FirmwareCompat> find(String firmwareVersion) {
        return jdbc.query("SELECT firmware_version, matrix_version, allowed_models"
                        + " FROM firmware_compat WHERE firmware_version = ?",
                (rs, rowNum) -> new FirmwareCompat(rs.getString("firmware_version"),
                        rs.getInt("matrix_version"), readModels(rs.getString("allowed_models"))),
                firmwareVersion).stream().findFirst();
    }

    public Optional<FirmwareCompat> findForUpdate(String firmwareVersion) {
        return jdbc.query("SELECT firmware_version, matrix_version, allowed_models"
                        + " FROM firmware_compat WHERE firmware_version = ? FOR UPDATE",
                (rs, rowNum) -> new FirmwareCompat(rs.getString("firmware_version"),
                        rs.getInt("matrix_version"), readModels(rs.getString("allowed_models"))),
                firmwareVersion).stream().findFirst();
    }

    /**
     * 首次配置：矩阵版本从 1 开始。
     */
    public void insert(String firmwareVersion, List<String> allowedModels) {
        jdbc.update("INSERT INTO firmware_compat (firmware_version, matrix_version, allowed_models)"
                + " VALUES (?, 1, ?)", firmwareVersion, writeModels(allowedModels));
    }

    /**
     * 乐观修改：仅当当前矩阵版本匹配时生效，版本加一，返回影响行数。
     */
