package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 设备登记请求。hardwareModel 可选，缺省等于设备型号；登记后不可修改。
 */
public record RegisterDeviceRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String deviceId,
        @NotBlank @Size(max = 64) String model,
        @Size(max = 64) String hardwareModel,
        @NotBlank @Size(max = 64) String currentVersion,
        @Min(0) @Max(99) int bucketNo) {

    /**
     * 兼容旧调用方：不传 hardwareModel 时使用设备型号。
     */
    public RegisterDeviceRequest(String requestId, String deviceId, String model,
                                 String currentVersion, int bucketNo) {
        this(requestId, deviceId, model, null, currentVersion, bucketNo);
    }

    /**
     * 有效硬件型号：未显式提供（或空白）时等于设备型号。
     */
    public String effectiveHardwareModel() {
        return hardwareModel == null || hardwareModel.isBlank() ? model : hardwareModel;
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.Device;

/**
 * 设备视图。
 */
public record DeviceView(String deviceId, String model, String hardwareModel,
                         String currentVersion, int bucketNo) {

    public static DeviceView of(Device device) {
        return new DeviceView(device.deviceId(), device.model(), device.hardwareModel(),
                device.currentVersion(), device.bucketNo());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

/**
 * 投放任务视图。compatVersion 为任务创建时目标固件的兼容矩阵版本（未配置矩阵为 0）。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion, int compatVersion) {

    public static TaskView of(RolloutTask task, ReleaseOrder order) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), task.compatVersion());
    }
}

package com.example.starter.firmware.api;

/**
 * 设备拉取响应。
 *
 * @param task   命中或已存在的任务；无匹配投放或被兼容矩阵拦截时为 null
 * @param result 拉取结果：TASK 返回任务，NONE 无匹配投放，INCOMPATIBLE 目标固件不兼容设备硬件型号
 */
public record PullResponse(TaskView task, String result) {

    public static PullResponse ofTask(TaskView task) {
        return new PullResponse(task, "TASK");
    }

    public static PullResponse none() {
        return new PullResponse(null, "NONE");
    }

    public static PullResponse incompatible() {
        return new PullResponse(null, "INCOMPATIBLE");
    }
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 配置固件硬件兼容矩阵请求。expectedVersion 为期望的当前矩阵版本（首次配置为 0）；
 * allowedModels 为空集合表示兼容全部型号，集合换序视为同参；型号重复或未知返回 422。
 */
public record ConfigureCompatRequest(
        @NotBlank @Size(max = 64) String requestId,
        @Min(0) int expectedVersion,
        @NotNull List<@NotBlank @Size(max = 64) String> allowedModels) {
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.FirmwareCompat;

import java.util.List;

/**
 * 固件硬件兼容矩阵视图。matrixVersion 为 0 表示从未配置（兼容全部型号）。
 */
public record FirmwareCompatView(String firmwareVersion, int matrixVersion, List<String> allowedModels) {

    public static FirmwareCompatView of(FirmwareCompat compat) {
        return new FirmwareCompatView(compat.firmwareVersion(), compat.matrixVersion(), compat.allowedModels());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.IncompatibleRecord;

/**
 * 设备不兼容拦截记录视图。
 */
public record IncompatibleRecordView(String deviceId, String hardwareModel, String firmwareVersion,
                                     int matrixVersion, String blockedAtUtc) {

    public static IncompatibleRecordView of(IncompatibleRecord record) {
        return new IncompatibleRecordView(record.deviceId(), record.hardwareModel(),
                record.firmwareVersion(), record.matrixVersion(), record.blockedAtUtc());
    }
}

package com.example.starter.firmware.api;

import java.util.List;

/**
 * 发布单的设备不兼容拦截记录列表。
 */
public record IncompatibleListResponse(long releaseId, List<IncompatibleRecordView> records) {
}

package com.example.starter.firmware.api;

import java.util.List;

/**
 * 发布单按硬件型号的投放统计。
 *
 * @param releaseId 发布单ID
 * @param stats     按硬件型号分组的统计，按型号升序
 */
public record ModelStatsResponse(long releaseId, List<ModelStats> stats) {

    /**
     * 单个硬件型号的投放统计。
     *
     * @param hardwareModel 硬件型号
     * @param pending       待回执任务数
     * @param success       成功任务数
     * @param failed        失败任务数
     * @param cancelled     已取消任务数
     * @param incompatible  被兼容矩阵拦截（未创建任务）的设备数
     */
    public record ModelStats(String hardwareModel, long pending, long success, long failed,
                             long cancelled, long incompatible) {
    }
}

